#!/bin/sh
# Generated by `coder-eval export --format harbor` — do not hand-edit; a
# regenerated export will overwrite it. See tmp/harborframework.md § C1.1.
#
# NOT `set -e`: `coder-eval evaluate` exits non-zero whenever any criterion
# fails its gate -- a genuine MEASURED verdict, not an infrastructure
# failure. `set -e` here would abort before `coder-eval harbor reward` ever
# ran, turning every real failing score into a masked (unmeasured) trial --
# confirmed live: a solution that runs but produces the wrong content
# scored weighted_score=0.500 in task.json, yet `set -e` discarded it and
# Harbor reported RewardFileNotFoundError instead of reward=0.5. The reward
# writer is what decides infra-vs-policy (None -> no file); this script must
# always reach it.
set -u

coder-eval evaluate /tests/task.yaml "/app" --in-place --run-dir /logs/verifier || true
coder-eval harbor reward /logs/verifier --out /logs/verifier/reward.json
